<body>
  <div class="app">
    <header>
      <div class="hero">
        <h1>Article Angle Brief Board</h1>
        <p class="sub">Compare article angles, shape title/meta/outline cards, then copy a compact brief.</p>
        <nav class="mini-nav" aria-label="Page shortcuts">
          <a href="#setup">Setup</a>
          <a href="#angles">Angles</a>
          <a href="#brief">Brief</a>
        </nav>
      </div>
    </header>

    <main>
      <section id="setup" class="card">
        <div class="section-title">
          <div>
            <h2>1. Topic and audience</h2>
            <p class="hint">Keep this rough. The brief gets cleaner as the cards improve.</p>
          </div>
        </div>

        <label for="topic">Topic</label>
        <input id="topic" type="text" placeholder="Example: Roth conversion mistakes for retirees">

        <label for="audience">Audience notes</label>
        <textarea id="audience" placeholder="Who is reading? What do they already know? What do they need to decide?"></textarea>

        <div class="grid-2">
          <div>
            <label for="goal">Search intent or reader job</label>
            <textarea id="goal" placeholder="Example: Wants a practical checklist before speaking with an advisor."></textarea>
          </div>
          <div>
            <label for="constraints">Constraints, claims, or must-include notes</label>
            <textarea id="constraints" placeholder="Example: Avoid tax advice tone. Mention Medicare IRMAA and withholding."></textarea>
          </div>
        </div>

        <div class="pill-row">
          <span class="pill">Local only</span>
          <span class="pill">No APIs</span>
          <span class="pill">Phone friendly</span>
        </div>
      </section>

      <section id="angles" class="card">
        <div class="section-title">
          <div>
            <h2>2. Compare 3 to 5 angles</h2>
            <p class="hint">Score each angle from 1 to 5. Tap “rank” when you want the strongest ideas on top.</p>
          </div>
        </div>

        <div class="actions">
          <button id="addAngle" type="button">Add angle</button>
          <button id="rankAngles" class="primary" type="button">Rank by score</button>
        </div>

        <div id="angleList" class="angle-list" aria-live="polite"></div>
      </section>

      <section id="cards" class="card">
        <div class="section-title">
          <div>
            <h2>3. Edit brief cards</h2>
            <p class="hint">Use these as the final article planning blocks.</p>
          </div>
        </div>

        <label for="titleCard">Working title</label>
        <textarea id="titleCard" placeholder="Write one strong title or a few title options."></textarea>

        <label for="metaCard">Meta description</label>
        <textarea id="metaCard" placeholder="Aim for a clear 140–160 character search snippet."></textarea>

        <label for="outlineCard">Outline</label>
        <textarea id="outlineCard" placeholder="H2/H3 structure, opening hook, examples, close."></textarea>

        <div class="grid-2">
          <div>
            <label for="faqCard">FAQ or objections</label>
            <textarea id="faqCard" placeholder="Questions the reader may ask before trusting the article."></textarea>
          </div>
          <div>
            <label for="ctaCard">CTA or next step</label>
            <textarea id="ctaCard" placeholder="What should the reader do after reading?"></textarea>
          </div>
        </div>

        <div class="actions">
          <button id="fillCards" type="button">Fill empty cards from top angle</button>
          <button id="clearCards" class="ghost" type="button">Clear cards</button>
        </div>
      </section>

      <section id="brief" class="card">
        <div class="section-title">
          <div>
            <h2>4. Copy article brief</h2>
            <p class="hint">Builds a concise handoff brief from your current board.</p>
          </div>
        </div>

        <div class="actions">
          <button id="buildBrief" class="primary" type="button">Build brief</button>
          <button id="copyBrief" class="good" type="button">Copy brief</button>
          <button id="downloadBrief" type="button">Download .txt</button>
          <button id="resetBoard" class="danger ghost" type="button">Reset board</button>
        </div>

        <label for="briefOutput">Generated brief</label>
        <textarea id="briefOutput" class="brief-output" placeholder="Your concise article brief will appear here."></textarea>
        <div id="status" class="status" role="status" aria-live="polite"></div>
      </section>

      <p class="footer-note">Everything runs in this file. Autosaves in this browser with localStorage.</p>
    </main>
  </div>

  <script>
    (function () {
      const storeKey = "article-angle-brief-board-v1";
      const maxAngles = 5;
      const minAngles = 3;

      const defaults = {
        topic: "",
        audience: "",
        goal: "",
        constraints: "",
        titleCard: "",
        metaCard: "",
        outlineCard: "",
        faqCard: "",
        ctaCard: "",
        briefOutput: "",
        angles: [
          makeAngle("Beginner explainer", "Clarify the topic for a reader who feels stuck or overloaded.", "Definitions, examples, simple decision path."),
          makeAngle("Mistakes and fixes", "Show the most common traps, then give practical corrections.", "Checklist, warning signs, before/after examples."),
          makeAngle("Decision framework", "Help the reader compare options and choose the right next step.", "Scoring rubric, scenarios, tradeoffs.")
        ]
      };

      let state = loadState();

      const els = {
        topic: document.getElementById("topic"),
        audience: document.getElementById("audience"),
        goal: document.getElementById("goal"),
        constraints: document.getElementById("constraints"),
        titleCard: document.getElementById("titleCard"),
        metaCard: document.getElementById("metaCard"),
        outlineCard: document.getElementById("outlineCard"),
        faqCard: document.getElementById("faqCard"),
        ctaCard: document.getElementById("ctaCard"),
        briefOutput: document.getElementById("briefOutput"),
        angleList: document.getElementById("angleList"),
        status: document.getElementById("status"),
        addAngle: document.getElementById("addAngle"),
        rankAngles: document.getElementById("rankAngles"),
        fillCards: document.getElementById("fillCards"),
        clearCards: document.getElementById("clearCards"),
        buildBrief: document.getElementById("buildBrief"),
        copyBrief: document.getElementById("copyBrief"),
        downloadBrief: document.getElementById("downloadBrief"),
        resetBoard: document.getElementById("resetBoard")
      };

      init();

      function makeId() {
        return "a" + Math.random().toString(36).slice(2, 10);
      }

      function makeAngle(name, promise, evidence) {
        return {
          id: makeId(),
          name: name || "",
          promise: promise || "",
          evidence: evidence || "",
          scores: {
            clarity: 3,
            intent: 3,
            freshness: 3,
            ease: 3
          }
        };
      }

      function loadState() {
        try {
          const raw = localStorage.getItem(storeKey);
          if (!raw) return structuredClone(defaults);
          const parsed = JSON.parse(raw);
          const merged = Object.assign(structuredClone(defaults), parsed);
          merged.angles = Array.isArray(parsed.angles) && parsed.angles.length >= minAngles
            ? parsed.angles.slice(0, maxAngles)
            : structuredClone(defaults.angles);
          merged.angles.forEach(angle => {
            angle.id = angle.id || makeId();
            angle.scores = Object.assign({ clarity: 3, intent: 3, freshness: 3, ease: 3 }, angle.scores || {});
          });
          return merged;
        } catch (e) {
          return structuredClone(defaults);
        }
      }

      function saveState() {
        try {
          localStorage.setItem(storeKey, JSON.stringify(state));
        } catch (e) {}
      }

      function init() {
        bindField("topic");
        bindField("audience");
        bindField("goal");
        bindField("constraints");
        bindField("titleCard");
        bindField("metaCard");
        bindField("outlineCard");
        bindField("faqCard");
        bindField("ctaCard");
        bindField("briefOutput");

        renderFields();
        renderAngles();

        els.addAngle.addEventListener("click", () => {
          if (state.angles.length >= maxAngles) return;
          state.angles.push(makeAngle("New angle", "", ""));
          saveState();
          renderAngles();
          setStatus("Angle added.");
        });

        els.rankAngles.addEventListener("click", () => {
          state.angles.sort((a, b) => totalScore(b) - totalScore(a));
          saveState();
          renderAngles();
          setStatus("Angles ranked by score.");
        });

        els.fillCards.addEventListener("click", fillEmptyCards);
        els.clearCards.addEventListener("click", clearCards);
        els.buildBrief.addEventListener("click", buildBrief);
        els.copyBrief.addEventListener("click", copyBrief);
        els.downloadBrief.addEventListener("click", downloadBrief);
        els.resetBoard.addEventListener("click", resetBoard);
      }

      function bindField(key) {
        els[key].addEventListener("input", () => {
          state[key] = els[key].value;
          saveState();
        });
      }

      function renderFields() {
        [
          "topic",
          "audience",
          "goal",
          "constraints",
          "titleCard",
          "metaCard",
          "outlineCard",
          "faqCard",
          "ctaCard",
          "briefOutput"
        ].forEach(key => {
          els[key].value = state[key] || "";
        });
      }

      function renderAngles() {
        els.angleList.innerHTML = "";
        const ranks = getRanks();

        state.angles.forEach((angle, index) => {
          const card = document.createElement("article");
          card.className = "angle-card";
          card.dataset.id = angle.id;

          card.innerHTML = `
            <div class="angle-top">
              <span class="badge"><span class="rank">#${ranks[angle.id]}</span> · <span data-score>${totalScore(angle)}</span>/20</span>
              <div class="small-buttons">
                <button type="button" data-action="duplicate">Duplicate</button>
                <button type="button" data-action="remove" class="danger" ${state.angles.length <= minAngles ? "disabled" : ""}>Remove</button>
              </div>
            </div>

            <label>Angle name or hook</label>
            <textarea data-field="name" placeholder="Example: The 5 mistakes people make before choosing a strategy">${escapeHtml(angle.name)}</textarea>

            <label>Reader promise</label>
            <textarea data-field="promise" placeholder="What useful result does this angle give the reader?">${escapeHtml(angle.promise)}</textarea>

            <label>Evidence, examples, or notes</label>
            <textarea data-field="evidence" placeholder="Stats, examples, screenshots, expert quotes, product notes, internal claims.">${escapeHtml(angle.evidence)}</textarea>

            ${scoreControl("clarity", "Clarity", angle.scores.clarity)}
            ${scoreControl("intent", "Intent fit", angle.scores.intent)}
            ${scoreControl("freshness", "Angle freshness", angle.scores.freshness)}
            ${scoreControl("ease", "Ease to write", angle.scores.ease)}
          `;

          card.addEventListener("input", event => {
            const target = event.target;
            const id = card.dataset.id;
            const item = state.angles.find(a => a.id === id);
            if (!item) return;

            if (target.matches("[data-field]")) {
              item[target.dataset.field] = target.value;
              saveState();
            }

            if (target.matches("[data-score-key]")) {
              item.scores[target.dataset.scoreKey] = Number(target.value);
              const row = target.closest(".score-row");
              row.querySelector("[data-score-value]").textContent = target.value;
              card.querySelector("[data-score]").textContent = totalScore(item);
              updateRankBadges();
              saveState();
            }
          });

          card.addEventListener("click", event => {
            const button = event.target.closest("button[data-action]");
            if (!button) return;
            const id = card.dataset.id;

            if (button.dataset.action === "remove") {
              if (state.angles.length <= minAngles) return;
              state.angles = state.angles.filter(a => a.id !== id);
              saveState();
              renderAngles();
              setStatus("Angle removed.");
            }

            if (button.dataset.action === "duplicate") {
              if (state.angles.length >= maxAngles) {
                setStatus("Maximum is 5 angles.");
                return;
              }
              const original = state.angles.find(a => a.id === id);
              if (!original) return;
              const copy = JSON.parse(JSON.stringify(original));
              copy.id = makeId();
              copy.name = copy.name ? copy.name + " copy" : "Copied angle";
              state.angles.splice(index + 1, 0, copy);
              saveState();
              renderAngles();
              setStatus("Angle duplicated.");
            }
          });

          els.angleList.appendChild(card);
        });

        els.addAngle.disabled = state.angles.length >= maxAngles;
        updateRankBadges();
      }

      function scoreControl(key, label, value) {
        const safeValue = Number(value) || 3;
        return `
          <div class="score-row">
            <label>${label}</label>
            <div class="score-wrap">
              <input type="range" min="1" max="5" value="${safeValue}" data-score-key="${key}" aria-label="${label}">
              <span class="score-value" data-score-value>${safeValue}</span>
            </div>
          </div>
        `;
      }

      function totalScore(angle) {
        const s = angle.scores || {};
        return ["clarity", "intent", "freshness", "ease"].reduce((sum, key) => sum + (Number(s[key]) || 0), 0);
      }

      function getRanks() {
        const sorted = [...state.angles].sort((a, b) => totalScore(b) - totalScore(a));
        const ranks = {};
        sorted.forEach((angle, index) => {
          ranks[angle.id] = index + 1;
        });
        return ranks;
      }

      function updateRankBadges() {
        const ranks = getRanks();
        document.querySelectorAll(".angle-card").forEach(card => {
          const id = card.dataset.id;
          const angle = state.angles.find(a => a.id === id);
          const rankEl = card.querySelector(".rank");
          const scoreEl = card.querySelector("[data-score]");
          if (rankEl) rankEl.textContent = "#" + ranks[id];
          if (scoreEl && angle) scoreEl.textContent = totalScore(angle);
        });
      }

      function topAngle() {
        return [...state.angles].sort((a, b) => totalScore(b) - totalScore(a))[0] || state.angles[0];
      }

      function fillEmptyCards() {
        const top = topAngle();
        const topic = clean(state.topic) || "the topic";
        const audience = clean(state.audience) || "the target reader";

        if (!clean(state.titleCard)) {
          state.titleCard = top.name && top.name !== "New angle"
            ? top.name
            : "How to think about " + topic;
        }

        if (!clean(state.metaCard)) {
          state.metaCard = trimTo(
            "A practical guide for " + audience + " on " + topic + ", with a clear angle, useful examples, and next steps.",
            160
          );
        }

        if (!clean(state.outlineCard)) {
          state.outlineCard = [
            "1. Open with the reader problem",
            "2. Define the topic in plain terms",
            "3. Present the core angle: " + (clean(top.name) || "main argument"),
            "4. Explain the key tradeoffs or mistakes",
            "5. Add examples, evidence, and practical notes",
            "6. Give the reader a short checklist",
            "7. Close with the next step"
          ].join("\n");
        }

        if (!clean(state.faqCard)) {
          state.faqCard = [
            "What does the reader misunderstand about this topic?",
            "When does this advice not apply?",
            "What should they check before acting?"
          ].join("\n");
        }

        if (!clean(state.ctaCard)) {
          state.ctaCard = "Use the checklist, compare the options, and take the next small step with better context.";
        }

        renderFields();
        saveState();
        setStatus("Empty cards filled from the top-ranked angle.");
      }

      function clearCards() {
        state.titleCard = "";
        state.metaCard = "";
        state.outlineCard = "";
        state.faqCard = "";
        state.ctaCard = "";
        renderFields();
        saveState();
        setStatus("Brief cards cleared.");
      }

      function buildBrief() {
        const top = topAngle();
        const ranked = [...state.angles].sort((a, b) => totalScore(b) - totalScore(a));
        const angleLines = ranked.map((angle, index) => {
          return `${index + 1}. ${clean(angle.name) || "Untitled angle"} — ${totalScore(angle)}/20`;
        }).join("\n");

        const brief = [
          "ARTICLE BRIEF",
          "",
          "Topic",
          clean(state.topic) || "[Add topic]",
          "",
          "Audience",
          clean(state.audience) || "[Add audience notes]",
          "",
          "Reader intent",
          clean(state.goal) || "[Add intent or reader job]",
          "",
          "Chosen angle",
          (clean(top.name) || "[Add chosen angle]") + " (" + totalScore(top) + "/20)",
          "",
          "Reader promise",
          clean(top.promise) || "[Add reader promise]",
          "",
          "Working title",
          clean(state.titleCard) || "[Add title]",
          "",
          "Meta description",
          clean(state.metaCard) || "[Add meta description]",
          "",
          "Outline",
          clean(state.outlineCard) || "[Add outline]",
          "",
          "Evidence and examples to collect",
          clean(top.evidence) || "[Add evidence notes]",
          "",
          "FAQ or objections",
          clean(state.faqCard) || "[Add FAQ or objections]",
          "",
          "CTA or next step",
          clean(state.ctaCard) || "[Add CTA]",
          "",
          "Constraints or must-include notes",
          clean(state.constraints) || "[Add constraints]",
          "",
          "Angle ranking",
          angleLines || "[Add angles]"
        ].join("\n");

        state.briefOutput = brief;
        els.briefOutput.value = brief;
        saveState();
        setStatus("Brief built.");
      }

      async function copyBrief() {
        if (!clean(state.briefOutput)) buildBrief();

        const text = els.briefOutput.value;
        try {
          if (navigator.clipboard && window.isSecureContext) {
            await navigator.clipboard.writeText(text);
          } else {
            els.briefOutput.focus();
            els.briefOutput.select();
            document.execCommand("copy");
          }
          setStatus("Brief copied.");
        } catch (e) {
          els.briefOutput.focus();
          els.briefOutput.select();
          setStatus("Copy failed. The brief is selected so you can copy manually.");
        }
      }

      function downloadBrief() {
        if (!clean(state.briefOutput)) buildBrief();

        const text = els.briefOutput.value;
        const safeTopic = (clean(state.topic) || "article-brief")
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, "-")
          .replace(/(^-|-$)/g, "")
          .slice(0, 48) || "article-brief";

        const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = safeTopic + ".txt";
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);
        setStatus("Brief downloaded.");
      }

      function resetBoard() {
        const ok = confirm("Reset the board and clear saved data?");
        if (!ok) return;
        state = structuredClone(defaults);
        try {
          localStorage.removeItem(storeKey);
        } catch (e) {}
        renderFields();
        renderAngles();
        setStatus("Board reset.");
      }

      function clean(value) {
        return String(value || "").trim();
      }

      function trimTo(text, limit) {
        if (text.length <= limit) return text;
        return text.slice(0, limit - 1).trimEnd() + "…";
      }

      function setStatus(message) {
        els.status.textContent = message;
        clearTimeout(setStatus.timer);
        setStatus.timer = setTimeout(() => {
          els.status.textContent = "";
        }, 2200);
      }

      function escapeHtml(value) {
        return String(value || "")
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#039;");
      }
    })();
  </script>
